// Compact figures for narrow cells: durations, token counts, dollars, clock time.

/** `<1m`, `42m`, `1h`, `4h36`, `3d3h`, `2d`, `∞`; negative reads as `<1m`. */
export const fmtDur = (ms: number): string => {
  if (ms === Infinity) return '∞'
  const s = Math.floor(Math.max(0, ms) / 1000)
  if (s < 60) return '<1m'
  const minutes = Math.round(s / 60)
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  const mins = minutes % 60
  if (hours < 24) return mins ? `${hours}h${String(mins).padStart(2, '0')}` : `${hours}h`
  const days = Math.floor(hours / 24)
  const hrs = hours % 24
  return hrs ? `${days}d${hrs}h` : `${days}d`
}

/** `300`, `140k`, `1M`, `1.5M`. */
export const fmtTokens = (n: number): string => {
  if (n < 1_000) return `${Math.round(n)}`
  if (Math.round(n / 1000) < 1_000) return `${Math.round(n / 1000)}k`
  return `${Math.round(n / 100_000) / 10}M`
}

/** `48s`, `1m12s`, `12m05s`; an hour and more read as `fmtDur`. */
export const fmtElapsed = (ms: number): string => {
  const s = Math.round(Math.max(0, ms) / 1000)
  if (s < 60) return `${s}s`
  if (s < 3_600) return `${Math.floor(s / 60)}m${String(s % 60).padStart(2, '0')}s`
  return fmtDur(ms)
}

/** `300`, `3.1k` below ten thousand, else as `fmtTokens`. */
export const fmtTokensFine = (n: number): string =>
  n >= 1_000 && n < 9_950 ? `${(Math.round(n / 100) / 10).toFixed(1)}k` : fmtTokens(n)

/** `$4.82` below a hundred, `$104` above. */
export const fmtUsd = (usd: number): string => (usd >= 100 ? `$${Math.round(usd)}` : `$${usd.toFixed(2)}`)

/** Local `HH:MM`. */
export const fmtClock = (epochMs: number): string => {
  const d = new Date(epochMs)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

/** A moment to come: `23:50` today, `tomorrow 17:00`, then `Oct 15 17:00`. */
export const fmtWhen = (epochMs: number, nowMs: number): string => {
  const at = new Date(epochMs)
  const day = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
  const days = Math.round((day(at) - day(new Date(nowMs))) / 86_400_000)
  if (days <= 0) return fmtClock(epochMs)
  if (days === 1) return `tomorrow ${fmtClock(epochMs)}`
  return `${MONTHS[at.getMonth()]} ${at.getDate()} ${fmtClock(epochMs)}`
}

files.types/index.d.ts:
/** One slice of the context window, in the colour /context gives its category. */
export type Segment = { label: string; tokens: number; color: string; kind: 'used' | 'free' | 'buffer' }

/** What the repo section draws; null fields are unknown, never zero. */
export type GitSnapshot = {
  cwd: string
  repo: string | null
  branch: string | null
  files: number | null
  added: number | null
  removed: number | null
  ahead: number | null
  behind: number | null
  sessionFiles: string[]
}

export type CardLine = 'model' | 'context' | 'five_hour' | 'seven_day' | 'cost' | 'repo'

/** `inline`: beside Claude Code's hint, one row; `below`: a row of its own under it, the hint kept as the engine draws it. */
export type HintLayout = 'inline' | 'below'

export type Settings = { cardLines: CardLine[]; barWidth: number; hintLayout: HintLayout }

export type Speed = { ttftMs: number; tokPerS: number | null }

/** Main-loop facts learnt from the session's events; null until seen. */
export type Live = {
  model: string | null
  effort: string | null
  permissionMode: string | null
  isWorking: boolean
  requests: number
  speed: Speed | null
}

/** What the mod counts itself, since `since` (load or /clear). */
export type Counters = { since: number; compactions: number; tools: Record<string, number>; subagents: number }

/** The running turn, or the last one. */
export type Receipt = {
  isRunning: boolean
  startedAt: number
  durationMs: number | null
  agents: number
  edits: number
  errors: number
  costAddedUsd: number | null
}

/** A rate-limit window, as `$.session.usage()` reads it. */
export type RateLimit = { kind: string; percentUsed: number; resetsAt?: string }

/** The part of the context breakdown the drawings read. */
export type BreakdownView = {
  categories: { name: string; tokens: number; color: string; kind: 'used' | 'free' | 'buffer' | 'deferred' }[]
  memoryFiles: { path: string; tokens: number }[]
  mcpTools: { name: string; serverName: string; tokens: number }[]
  agents: { agentType: string; tokens: number }[]
  skills?: { totalSkills: number; tokens: number; items: { name: string; tokens: number }[] }
  autoCompactThreshold?: number
  isAutoCompactEnabled: boolean
  autocompactSource: string
}

/** The session's readings as the drawings use them. */
export type UsageView = {
  startedAt: number
  tokens?: number
  window: number
  rateLimits: RateLimit[]
  costUsd?: number
  prompts: number
  breakdown: BreakdownView | null
  breakdownDetail: 'summary' | 'full'
}

export type AgentState = 'running' | 'done' | 'failed' | 'stopped'
export type AgentCall = { tool: string; detail: string | null }
/** One subagent, as the Agents box draws it. */
export type AgentCard = {
  id: string
  type: string
  task: string
  startedAt: number
  endedAt: number | null
  state: AgentState
  steps: number
  contextTokens: number | null
  outputTokens: number
  calls: AgentCall[] // newest last, at most three
}

/** Inside `declare module 'claude-code'` a bare `Settings` names the engine's own; this one is the mod's. */
export type ModSettings = Settings

declare module 'claude-code' {
  interface PluginState {
    'session-status': {
      usage: UsageView | null
      live: Live
      counters: Counters
      receipt: Receipt | null
      git: GitSnapshot | null
      settings: ModSettings
      expanded: string[]
      agents: AgentCard[]
    }
  }
}
